package nl.atlas.gallery.featureeditor.filter

/** Source catalogue for assets generated by tools/atlas_luts/generate_luts.py. */
data class AtlasFilter(val id: String, val displayName: String, val previewStrength: Double = 0.72)

object AtlasFilterCatalogue {
    val looks = listOf(
        AtlasFilter("atlas-clear", "Clear Air"), AtlasFilter("atlas-hearth", "Hearth"),
        AtlasFilter("atlas-drift", "Blue Drift"), AtlasFilter("atlas-moss", "Moss Path"),
        AtlasFilter("atlas-amber", "Amber Hour"), AtlasFilter("atlas-slate", "Slate"),
        AtlasFilter("atlas-linen", "Linen"), AtlasFilter("atlas-orchard", "Orchard"),
        AtlasFilter("atlas-coast", "Quiet Coast"), AtlasFilter("atlas-copper", "Copper Leaf"),
        AtlasFilter("atlas-dawn", "Dawn Glass"), AtlasFilter("atlas-pine", "Pine Shade"),
        AtlasFilter("atlas-bloom", "Soft Bloom"), AtlasFilter("atlas-ink", "Atlas Ink"),
    )
    private val byId = looks.associateBy(AtlasFilter::id)
    fun find(id: String): AtlasFilter? = byId[id]
}
